import copy
import hashlib
import json

STATUS_ORDER = {"DRAFT": 0, "SUBMITTED": 1, "AUTHORISED": 2}
# The highest Xero status the agent may set, by the client's approval route. Any other route: Draft only.
MAX_STATUS = {"bookkeeper": "AUTHORISED", "hj_reviewer": "AUTHORISED", "client_each_bill": "SUBMITTED"}


class Refused(Exception):
    def __init__(self, code, reason):
        super().__init__(reason)
        self.code = code
        self.reason = reason


def as_data(value):
    if isinstance(value, str):
        try:
            return json.loads(value)
        except Exception:
            return value
    return value


def tidy(value):
    """The same value however it was written: 100 and 100.0 compare equal."""
    value = as_data(value)
    if isinstance(value, dict):
        return {str(k): tidy(v) for k, v in value.items()}
    if isinstance(value, list):
        return [tidy(v) for v in value]
    if isinstance(value, float) and value.is_integer():
        return int(value)
    return value


def approval_digest(action, tenant, invoice, invoice_id, patch):
    body = {"action": action, "xero_tenant_id": tenant}
    if action == "create":
        body["invoice"] = invoice
    else:
        body["invoice_id"] = invoice_id
        body["patch"] = patch
    text = json.dumps(tidy(body), sort_keys=True, separators=(",", ":"), ensure_ascii=False)
    return hashlib.sha256(text.encode("utf-8")).hexdigest()[:12]


def approval_from_params():
    action = str(params.get("action") or "").strip().lower()
    tenant = str(params.get("xero_tenant_id") or "").strip()
    invoice = tidy(params.get("invoice")) if action == "create" else None
    invoice_id = str(params.get("invoice_id") or "").strip() if action == "update" else ""
    patch = tidy(params.get("patch")) if action == "update" else None
    return action, tenant, invoice, invoice_id, patch


def first_invoice(value):
    value = as_data(value)
    if isinstance(value, dict):
        rows = value.get("Invoices") or value.get("invoices")
        if isinstance(rows, list):
            return rows[0] if rows and isinstance(rows[0], dict) else {}
        if value.get("InvoiceID"):
            return value
    if isinstance(value, list) and value and isinstance(value[0], dict):
        return value[0]
    return {}


def all_invoices(value):
    value = as_data(value)
    if isinstance(value, dict):
        rows = value.get("Invoices") or value.get("invoices") or []
        return [r for r in rows if isinstance(r, dict)]
    if isinstance(value, list):
        return [r for r in value if isinstance(r, dict)]
    return []


def amount(value):
    try:
        return round(float(value), 4)
    except Exception:
        return None


def get_record(type_slug, record_id):
    if not record_id:
        return {}
    row = as_data(api.records.get(type_slug=type_slug, record_id=record_id))
    if isinstance(row, dict) and isinstance(row.get("record"), dict):
        row = row["record"]
    return row if isinstance(row, dict) else {}


def field(row, key):
    data = row.get("data") or row.get("fields") or {}
    return data.get(key, row.get(key))


def client_id_of(row):
    links = row.get("links") if isinstance(row.get("links"), dict) else {}
    found = links.get("client") or field(row, "client")
    if isinstance(found, list):
        found = found[0] if found else ""
    if isinstance(found, dict):
        found = found.get("id") or found.get("record_id") or ""
    return str(found or "")


def bill_context(record_id, tenant):
    """The AP bill row, its client's approval route, and a check that the Xero organisation is that client's."""
    row = get_record("ap_bill", record_id)
    if not row:
        raise Refused("bad_input", "The AP bill row couldn't be read.")
    client = get_record("client", client_id_of(row))
    route = str(field(row, "approval_route") or field(client, "ap_approval_route") or "").strip().lower()
    given = str(params.get("route") or "").strip().lower()
    if given and given != route:
        raise Refused("route", f"The route given ({given}) isn't this client's route ({route or 'none'}).")
    row_tenant = str(field(row, "xero_tenant_id") or "").strip()
    client_tenant = str(field(client, "ap_xero_tenant_id") or "").strip()
    if (row_tenant and row_tenant != tenant) or (client_tenant and client_tenant != tenant):
        raise Refused("tenant", "That Xero organisation isn't the one this bill's client uses.")
    return row, route


def same_supplier(bill, contact):
    theirs = bill.get("Contact") or {}
    if contact.get("ContactID") and theirs.get("ContactID"):
        return contact.get("ContactID") == theirs.get("ContactID")
    mine = str(contact.get("Name") or "").strip().lower()
    return bool(mine) and mine == str(theirs.get("Name") or "").strip().lower()


def in_job():
    return str((trigger or {}).get("kind") or "") == "process"


def as_list(value):
    return value if isinstance(value, list) else []


def cut(value, limit):
    """Trim to `limit` characters as the platform counts them (UTF-16 units)."""
    text = " ".join(("" if value is None else str(value)).split())
    while len(text.encode("utf-16-le")) // 2 > limit:
        text = text[:-1]
    return text


def tracking_text(tracking):
    parts = []
    for t in tracking or []:
        if isinstance(t, dict):
            parts.append(f"{t.get('Name') or ''}: {t.get('Option') or ''}".strip(": "))
    return ", ".join(p for p in parts if p)


def coding_text(line):
    bits = [str(line.get("AccountCode") or ""), str(line.get("TaxType") or ""), tracking_text(line.get("Tracking"))]
    return " / ".join(b for b in bits if b)


def line_amount(line):
    if line.get("LineAmount") is not None:
        return amount(line.get("LineAmount"))
    qty, unit = amount(line.get("Quantity")), amount(line.get("UnitAmount"))
    if qty is not None and unit is not None:
        return round(qty * unit, 2)
    return None


def build():
    action, tenant, bill, bill_id, patch = approval_from_params()
    digest = approval_digest(action, tenant, bill, bill_id, patch) if action in ("create", "update") else ""
    originals = [cut(s, 500) for s in (as_data(params.get("original_lines")) or []) if isinstance(s, str)]
    notes = [cut(s, 300) for s in (as_data(params.get("line_notes")) or []) if isinstance(s, str)]
    rows = []
    status_line = ""
    total = 0.0
    amounts_type = ""
    if action == "create" and isinstance(bill, dict):
        amounts_type = str(bill.get("LineAmountTypes") or "")
        status_line = f"Xero status after approval: {bill.get('Status') or 'not given'}"
        for n, line in enumerate([l for l in as_list(bill.get("LineItems")) if isinstance(l, dict)], start=1):
            value = line_amount(line)
            total += value or 0
            rows.append({"key": str(n), "label": f"Line {n}", "original": originals[n - 1] if n <= len(originals) else "",
                         "problem": notes[n - 1] if n <= len(notes) else "",
                         "values": {"description": cut(line.get("Description"), 300) or None, "amount": value,
                                    "account": cut(line.get("AccountCode"), 300) or None, "tax_type": cut(line.get("TaxType"), 300) or None,
                                    "tracking": cut(tracking_text(line.get("Tracking")), 300) or None}})
    elif action == "update" and isinstance(patch, dict):
        current = {}
        if in_job() and tenant and bill_id:
            current = first_invoice(api.connectors.invoke(server="xero-accounting", tool="get_invoice", args={"xero_tenant_id": tenant, "invoiceId": bill_id}))
        amounts_type = str(current.get("LineAmountTypes") or "")
        status_line = f"Xero status after approval: {patch.get('Status') or current.get('Status') or 'unchanged'}"
        proposed = {str(l.get("LineItemID")): l for l in as_list(patch.get("LineItems")) if isinstance(l, dict)}
        for n, now in enumerate([l for l in (current.get("LineItems") or []) if isinstance(l, dict)], start=1):
            new = dict(now, **{k: v for k, v in proposed.get(str(now.get("LineItemID")), {}).items() if k in ("Description", "AccountCode", "TaxType", "Tracking")})
            value = line_amount(now)
            total += value or 0
            changed = coding_text(now) != coding_text(new)
            note = notes[n - 1] if n <= len(notes) else ""
            if changed and not note:
                note = f"Changed from {coding_text(now) or 'nothing'}"
            rows.append({"key": str(n), "label": f"Line {n}", "original": cut(coding_text(now), 500), "problem": cut(note, 300),
                         "values": {"description": cut(new.get("Description"), 300) or None, "amount": value,
                                    "account": cut(new.get("AccountCode"), 300) or None, "tax_type": cut(new.get("TaxType"), 300) or None,
                                    "tracking": cut(tracking_text(new.get("Tracking")), 300) or None}})
    for row in rows:
        for key in ("original", "problem"):
            if not row[key]:
                row.pop(key)
    if not rows:
        rows = [{"key": "1", "label": "Bill", "problem": "No lines to show.", "values": {"description": None, "amount": None, "account": None, "tax_type": None, "tracking": None}}]
    summary = [s for s in [status_line, f"Lines total {round(total, 2)}" + (f" (amounts {amounts_type.lower()} of GST)" if amounts_type in ("Inclusive", "Exclusive") else ""), f"Check code {digest}" if digest else ""] if s]
    summary += [cut(s, 300) for s in (as_data(params.get("summary")) or []) if isinstance(s, str) and s.strip()]
    sheet = {
        "title": cut(params.get("title"), 200) or "Supplier bill",
        "summary": summary[:8],
        "originalLabel": cut(params.get("original_label"), 40) or ("In Xero now" if action == "update" else "On the bill"),
        "proposedLabel": cut(params.get("proposed_label"), 40) or ("After approval" if action == "update" else "To enter in Xero"),
        "columns": [
            {"key": "description", "label": "Description"},
            {"key": "amount", "label": "Amount"},
            {"key": "account", "label": "Account", "edit": "text"},
            {"key": "tax_type", "label": "Tax code", "edit": "text"},
            {"key": "tracking", "label": "Tracking", "edit": "text"},
        ],
        "rows": rows[:300],
    }
    # Keep the sheet well inside the platform's 64 KiB limit for one output.
    while len(json.dumps(sheet)) > 60000:
        for row in sheet["rows"]:
            if "original" in row:
                row["original"] = row["original"][: max(0, len(row["original"]) // 2)]
            row["values"]["description"] = (row["values"]["description"] or "")[:60] or None
        if len(json.dumps(sheet)) > 60000:
            sheet["rows"] = sheet["rows"][: max(1, len(sheet["rows"]) // 2)]
            sheet["summary"] = (sheet["summary"] + ["Only the first lines are shown here."])[:8]
    return sheet, digest, round(total, 2)


